SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/fa18a1959b2da9d075b4d34cc550c3a09bdc12eb/content/books/zizhi-tongjian/vol-294/year-0958/part-02/sources/library/jiuwudaishi-118-february-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002781；EPUB电子本，纸本及异文待核", "id": "01256150-f2ed-528c-bf4a-8dcbefff1e32"}, {"title": "宋史·巻二百五十五", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/fa18a1959b2da9d075b4d34cc550c3a09bdc12eb/content/books/zizhi-tongjian/vol-294/year-0958/part-02/sources/library/songshi-255-xizhou-defense/source.txt", "note": "《宋史》巻二百五十五，段落 songshi-9c6e46fee832-p057546；EPUB电子本，纸本及异文待核", "id": "5b7bd48a-22bc-50cd-839d-f6e685a3fb70"}, {"title": "宋史·巻二百五十五", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/fa18a1959b2da9d075b4d34cc550c3a09bdc12eb/content/books/zizhi-tongjian/vol-294/year-0958/part-02/sources/library/songshi-255-yangtingzhang-early-career/source.txt", "note": "《宋史》巻二百五十五，段落 songshi-9c6e46fee832-p057543；EPUB电子本，纸本及异文待核", "id": "b564143f-ac2b-5dbc-8d70-4c7906cdf921"}, {"title": "宋史·巻二百五十五", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/fa18a1959b2da9d075b4d34cc550c3a09bdc12eb/content/books/zizhi-tongjian/vol-294/year-0958/part-02/sources/library/songshi-255-yangtingzhang-family/source.txt", "note": "《宋史》巻二百五十五，段落 songshi-9c6e46fee832-p057542；EPUB电子本，纸本及异文待核", "id": "8aaeba96-433e-5147-b269-b63389d58cc7"}, {"title": "宋史·巻四百七十八", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/fa18a1959b2da9d075b4d34cc550c3a09bdc12eb/content/books/zizhi-tongjian/vol-294/year-0958/part-02/sources/library/songshi-478-licongjia-identity/source.txt", "note": "《宋史》巻四百七十八，段落 songshi-9c6e46fee832-p074872；EPUB电子本，纸本及异文待核", "id": "499c15e4-14c0-57b5-9ea9-bf2a7da8ba60"}, {"title": "宋史·巻四百七十八", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/fa18a1959b2da9d075b4d34cc550c3a09bdc12eb/content/books/zizhi-tongjian/vol-294/year-0958/part-02/sources/library/songshi-478-southern-tang-succession/source.txt", "note": "《宋史》巻四百七十八，段落 songshi-9c6e46fee832-p074873；EPUB电子本，纸本及异文待核", "id": "4d18a823-5a52-50fc-bf9c-f27c45a10f86"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8ed915b0f3bf92daf19318ca9962a9e6c2c54f00/content/books/zizhi-tongjian/vol-294/year-0958/part-01/sources/library/tongjian-294-958-spring/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003486；电子底本待考，分段待核", "id": "4e99a784-f6f3-5071-813c-d629a46340d6"}, {"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8ed915b0f3bf92daf19318ca9962a9e6c2c54f00/content/books/zizhi-tongjian/vol-294/year-0958/part-01/sources/library/jiuwudaishi-118-march-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002782；EPUB电子本，纸本及异文待核", "id": "8af10a4a-0c69-5b2f-bbe1-167e16e440ad"}]'::jsonb)
