INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "易文赟", "aliases": ["易文贇", "易赟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐建武军使，958年天长改雄州时受任刺史，二月甲寅率城降周。《旧五代史》姓名省作易赟，沿同城同职归降相联系。生卒年未载。", "biography": null, "status": "draft", "id": "246f5426-4465-532c-8521-f9c6107a2c23"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "韩令坤", "aliases": ["韓令坤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "磁州武安人，后周侍卫马军都指挥使。955年十一月，奉柴荣命与其他十一名将领随李谷、王彦超出征南唐。生卒年未载。", "biography": null, "status": "draft", "id": "808ffe02-5578-55cc-8c1f-2b9823cfd253"}, {"name": "司超", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "元城人，后周巡检使。956年二月奏报在盛唐击败南唐兵并俘高弼等。《通鉴》职名中庐、拜、光、黄的拜字可疑，《旧五代史》记庐寿巡检使，字形及职辖详略保留待核。", "biography": null, "status": "draft", "id": "8768f754-a204-5b14-ad70-40fb57a9f90d"}, {"name": "王审琦", "aliases": ["王審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "洛阳人，后周铁骑都指挥使，字仲宝。956年舒州人逐郭令图后，选轻骑夜袭恢复舒州。《宋史》记其先世辽西、后迁洛阳及早年在郭威军中履历，生卒年待后续补录。", "biography": null, "status": "draft", "id": "26929070-4b43-5b96-9683-d93666d18723"}, {"name": "施仁望", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐舒州刺史。958年二月，后周司超、王审琦攻舒州，他被俘获，具体交战日未独立记载。生卒年未载。", "biography": null, "status": "draft", "id": "896232d9-aa92-5b97-934a-422cb577ee0f"}, {"name": "孙议", "aliases": ["孫議"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周隰州刺史。958年战事条回述其突然去世，杨廷璋随即安排李谦溥代理州务。具体死亡年月未独载，不补死因。", "biography": null, "status": "draft", "id": "d9040c65-0269-5fe8-8f7b-6a6263088fd8"}, {"name": "杨廷璋", "aliases": ["楊廷璋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，后周建雄节度使。958年二月条下记隰州换守、与李谦溥协力夜袭北汉围军并奏报。《宋史》记其字温玉、姐姐曾为郭威淑妃，早年从郭威左右任军职。生卒年未载。", "biography": null, "status": "draft", "id": "55ed28fe-20db-5c62-a87b-0ae889fe4cc2"}, {"name": "李谦溥", "aliases": ["李謙溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周供备库副使。954年四月独自骑马说服辽州刺史投降后周。《宋史》也记同一职务与劝降行动，但把刺史姓名写作张乙，与《通鉴》张汉超不同。生卒年未载。", "biography": null, "status": "draft", "id": "ad5a349d-9360-5198-8d97-ba454f7202ae"}, {"name": "杨廷璋姊（郭威淑妃）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨廷璋的姐姐，姓名未载。《宋史》记其寡居京师，后来与郭威婚配，去世后在郭威即位时被追册淑妃。具体婚配与去世年日未载。", "biography": null, "status": "draft", "id": "2d26a9c7-cbde-56b5-b35a-0e4ac73581ed"}, {"name": "杨洪裕", "aliases": ["楊洪裕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨廷璋之父，史书本段称洪裕。郭威即位后，杨廷璋辞右飞龙使职，愿推恩父亲，洪裕以老病辞赴阙，获就拜金紫光禄大夫、真定少尹。生卒年未载。", "biography": null, "status": "draft", "id": "bcc8cd9c-5004-5285-a833-a9aeb164b64c"}, {"name": "徐景遂", "aliases": ["景遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景遂，获任者。", "biography": null, "status": "draft", "id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李弘冀", "aliases": ["弘冀", "李冀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李璟的长子。943年七月条下被立为南昌王。姓名在《资治通鉴》作弘冀，《新五代史》同一册封作冀；沿用同一主体，不因姓名省写再建李冀。生卒年尚未核。", "biography": null, "status": "draft", "id": "e4027731-d3e9-5cd1-8c58-d504f38025da"}, {"name": "李从嘉", "aliases": ["李從嘉", "从嘉", "李煜", "李后主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李璟第六子，李弘冀的弟弟，当时封安定公，后来名李煜。《宋史》明确本名从嘉。958年弘冀掌东宫后，他因畏惧哥哥而不参与政务，以读书自娱。生卒年本批未核。", "biography": null, "status": "draft", "id": "fa94de5d-24bb-5819-be0e-e4ebb6fcbaf2"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
